from patch import patch
# p04
patch('p04',"Les auteurs de la revue de 2026 écrivent","Les auteurs d'une revue récente écrivent que le bilan d'une ESV vise d'abord à identifier ou à exclure une cardiopathie structurelle sous-jacente{R61}.")
patch('p04',"Ils ajoutent que cette évaluation","Ils ajoutent que cette évaluation doit aussi rechercher des maladies non cardiovasculaires, car les ESV fréquentes s'associent à de nombreuses comorbidités{R11}.")
patch('p04',"Une étude japonaise de 6 332 patients","Une étude japonaise a suivi des patients sans cardiopathie structurelle. La fréquence des ESV n'était pas associée à la mortalité ni à l'insuffisance cardiaque{R18}. En revanche, la présence d'une arythmie ventriculaire non soutenue était associée à un risque plus élevé d'hospitalisation pour insuffisance cardiaque{R18}.")
patch('p04',"Deuxième diagnostic grave : la cardiomyopathie","Le deuxième diagnostic grave est la cardiomyopathie hypertrophique (DX.10, rang E2, 🚩), qui représente environ 5 % des cardiopathies que l'imagerie par résonance magnétique cardiaque découvre chez les patients avec arythmies ventriculaires significatives{CM5}.")
patch('p04',"Premier diagnostic à exclure","Le premier diagnostic à exclure est la tachycardie ventriculaire sur cardiopathie structurelle (DX.9, rang E1, 🚩).")
patch('p04',"Troisième diagnostic de rang élevé","Le troisième diagnostic de rang élevé est la voie accessoire, dont le syndrome de Wolff-Parkinson-White (DX.8, rang E3, 🚩).")
patch('p04',"La revue systématique de 2024 rapporte","La revue systématique rapporte que la prévalence de cardiopathie structurelle après IRM atteignait 24 % chez les patients avec ESV ou tachycardie ventriculaire non soutenue{CM5}. Elle atteignait 63 % chez ceux qui avaient des arythmies ventriculaires plus complexes{CM5}.")
patch('p04',"Une revue systématique de patients avec ESV fréquentes","Une revue systématique décrit trois critères d'alerte chez les patients avec ESV fréquentes et échocardiographie normale{SH5}. Ce sont la morphologie de bloc de branche droit avec axe supérieur ou intermédiaire, la reproductibilité des arythmies à l'effort et la présence d'arythmies complexes{SH5}.")
patch('p04',"La notice suisse du propranolol cite","La notice suisse du propranolol cite d'ailleurs l'hyperthyroïdie et les crises thyréotoxiques parmi ses indications, car ces états entraînent des tachycardies{aips-47025-1}.")
patch('p04',"Dans une méta-analyse de neuf études","Une méta-analyse de neuf études a inclus 62 000 participants{R20}. Les ESV en récupération étaient associées à un risque accru de décès, avec un risque relatif de 1.55{R20}. Les ESV pendant l'effort n'atteignaient pas la significativité, avec un risque relatif de 1.14{R20}.")
patch('p04',"Les personnes sans symptôme et avec une charge d'ESV faible","Les personnes sans symptôme et avec une charge d'ESV faible, de l'ordre de 5 %, n'ont pas besoin d'investigations supplémentaires{P7}.")
# p05
patch('p05',"Une anamnèse complète couvre","Une anamnèse complète couvre les symptômes, les facteurs précipitants, la pathologie cardiaque connue, le profil de risque cardiovasculaire et les médicaments. Elle comprend aussi les antécédents et l'histoire familiale{R11}.")
patch('p05',"Le colloque de médecine de premier recours","Le colloque de médecine de premier recours des Hôpitaux universitaires de Genève liste quatre questions{B1}. Elles portent sur ce qui précède le début, le mode de démarrage, le type de palpitations et la fin de l'épisode{B1}.")
patch('p05',"La consommation de café, en revanche, n'est pas associée","La consommation de café, en revanche, n'est pas associée à un risque d'arythmie plus élevé dans une grande cohorte{CO4}.")
patch('p05',"Un battement manqué isolé, sans salve, ne suit pas","Un battement manqué isolé, sans salve, ne suit pas cette dynamique{H12}.")
# p06
patch('p06',"Le pathologique mérite attention","Le pathologique mérite attention, car l'hypertension est associée à une charge d'ESV plus élevée. Elle fait passer la prévalence de 5 % à 23 %{R7}. Le rapport taille-hanches et la taille supérieure à la médiane figurent aussi parmi les facteurs de risque identifiés à Bâle{V4}.")
patch('p06',"L'hypertension fait passer la prévalence des ESV de 5 % à 23 %{R7}.","")
patch('p06',"Un patient avec ESV très fréquentes, une fatigue","Un patient avec ESV très fréquentes, une fatigue et une baisse de tolérance à l'effort est examiné pour une cardiomyopathie induite. Cette cardiomyopathie est réversible lorsque les ESV sont supprimées{R22}.")
patch('p06',"L'examen physique d'un patient qui consulte pour des palpitations a une double fonction","L'examen physique d'un patient qui consulte pour des palpitations a une double fonction : chercher les signes d'une cardiopathie ou d'une cause extracardiaque, et corréler le symptôme au pouls.")
# p07
patch('p07',"Ce syndrome correspond à la situation de la majorité","Ce syndrome correspond à la situation de la majorité des patients. Ceux qui n'ont pas de cardiopathie et dont la charge d'ESV est faible peuvent être rassurés quant à leur pronostic{F3} ([[f1|pause et bradysphygmie]]).")
patch('p07',"Le signe physique manque, mais le pronostic est marqué","Le signe physique manque, mais le pronostic est marqué. Dans la cohorte de Copenhague, le risque de décès ou d'accident vasculaire cérébral était significativement plus élevé, avec un rapport de risque de 1.64{C4}.")
patch('p07',"Dans ces situations, la suppression des ESV peut sauver la vie","Dans ces situations, la suppression des ESV peut sauver la vie{R33}. Les sites intracavitaires et le réseau de Purkinje comptent parmi les origines les plus fréquentes des ESV déclenchant une fibrillation ventriculaire{R53}.")
# p08
patch('p08',"Dans la cohorte suédoise, l'exclusion d'une cardiopathie reposait","Dans la cohorte suédoise, l'exclusion d'une cardiopathie reposait sur un échocardiogramme normal{S14}. Il se définissait par une fraction d'éjection du ventricule gauche d'au moins 55 %, l'absence de valvulopathie plus que légère, des dimensions ventriculaires normales et une épaisseur pariétale normale{S14}.")
patch('p08',"Une charge supérieure à 10–15 % a été associée à une dysfonction","Une charge supérieure à 10–15 % a été associée à une dysfonction ventriculaire gauche chez des patients au cœur auparavant normal{R32}. Elle l'a aussi été à une aggravation de la fonction chez ceux qui ont déjà une cardiomyopathie{R32}.")
patch('p08',"Les ESA fréquentes se définissent sur un Holter","Les ESA fréquentes se définissent sur un Holter de 24 à 48 heures{Z5}. La simple présence d'au moins une ESA sur un électrocardiogramme standard ne suffit pas pour prédire une fibrillation auriculaire ultérieure{Z5}.")
patch('p08',"Le tableau réunit les critères","Le tableau réunit les critères avec leur usage, car chaque seuil sert à décider d'une conduite et non à poser un diagnostic de maladie.")
# p09
patch('p09',"Le recueil de l'ESV elle-même","Le recueil de l'ESV elle-même sur le tracé compte beaucoup. L'électrocardiogramme de 12 dérivations a en effet une grande précision spatiale pour déterminer le site d'origine chez les patients au cœur structurellement normal{R37}.")
patch('p09',"Un examen normal est défini dans la cohorte suédoise","Un examen normal est défini dans la cohorte suédoise par une fraction d'éjection du ventricule gauche d'au moins 55 %{S14}. Il exige aussi l'absence de valvulopathie plus que légère, des dimensions normales et une épaisseur pariétale normale{S14}.")
patch('p09',"La morphologie de l'ESV dans la dérivation V1 identifie","La morphologie de l'ESV dans la dérivation V1 permet d'identifier le motif de bloc de branche{R39}. Un bloc de branche droit indique une origine du ventricule gauche{R39}. Un bloc de branche gauche indique une origine du ventricule droit ou du septum{R39}. [[f2|Lire l'axe, le QRS et la zone de transition]]")
patch('p09',"Un bloc de branche droit indique une origine du ventricule gauche, et","")
patch('p09',"L'imagerie par résonance magnétique cardiaque est envisagée si une cardiopathie autre","L'imagerie par résonance magnétique cardiaque est envisagée si une cardiopathie autre que coronarienne est suspectée d'après le bilan initial{R11}.")
patch('p09',"La cartographie de stimulation sert aux ESV peu fréquentes.","La cartographie de stimulation sert aux ESV peu fréquentes.")
patch('p09',"Cet examen offre donc une alternative","Cet examen est donc une alternative pour détecter une dysfonction subtile quand la fraction d'éjection paraît normale{R29}.")
patch('p09',"Le bilan biologique cherche les causes simples.","Le bilan biologique permet de chercher les causes simples.")
